def solve_hash(words):
    s=set()
    for w in words:
        for i in range(len(w)):
            s.add(w[:i+1])
    return s

class Node:
    def __init__(self):
        self.next={}; self.end=False
class Trie:
    def __init__(self):
        self.root=Node()
    def insert(self,w):
        cur=self.root
        for ch in w:
            cur=cur.next.setdefault(ch, Node())
        cur.end=True
